  'landing.faq.title': 'Frequently asked questions',
  'landing.faq.q1': 'Is Second Brain just a chatbot?',
  'landing.faq.a1': 'No. It’s a personal learning environment: it understands your content, teaches it, and remembers your progress over time.',
  'landing.faq.q2': 'Can I work with several PDFs and documents?',
  'landing.faq.a2': 'Yes. You can group PDFs, photos, scans and notes into a whole subject and learn from the full set, not a single file.',
  'landing.faq.q3': 'What can I do with the AI Professor?',
  'landing.faq.a3': 'Get taught, ask for explanations, discuss, run guided sessions and practise with exercises — adapted to your level.',
  'landing.faq.q4': 'Can I talk to the AI Professor out loud?',
  'landing.faq.a4': 'Yes. Spoken conversation, oral exercises and oral exams let you practise out loud.',
  'landing.faq.q5': 'What is the Digital Twin?',
  'landing.faq.a5': 'A personalized memory of your learning — what you understand, master, forget and aim for.',
  'landing.faq.q6': 'How do memory and review work?',
  'landing.faq.a6': 'A spaced-repetition engine (FSRS) schedules reviews at the right moment so you retain more with less effort.',
  'landing.faq.q7': 'Can I use Second Brain for my academic work?',
  'landing.faq.a7': 'Yes. The Academic Workspace guides labs, homework, reports and more — teaching the method, not just the answer.',
  'landing.faq.q8': 'How does language learning work?',
  'landing.faq.a8': 'Immersion, conversation, oral practice and shadowing — and help understanding the language of your own curriculum.',
  'landing.faq.q9': 'How is my data protected?',
  'landing.faq.a9': 'Your learning data powers your experience. You control your account and can manage your data from your profile.',

