  'landing12.faq.title': 'Questions? We answer them.',
  'landing12.faq.lead': 'Short answers about what the product really does today.',
  'landing12.faq.q1': 'What is Second Brain?',
  'landing12.faq.a1': 'A personal intelligent learning system that connects questions, sources, teaching, practice, memory and academic work in one context.',
  'landing12.faq.q2': 'Is it simply a chatbot?',
  'landing12.faq.a2': 'No. Conversation is one interface. The same session can become a lesson, an oral exercise, a sourced document question, a review or a Workspace action.',
  'landing12.faq.q3': 'How does My Brain work?',
  'landing12.faq.a3': 'It makes your concepts, relationships, mastery evidence, memory and learning history visible. It adapts its view to the maturity of available data.',
  'landing12.faq.q4': 'Can I use my own documents?',
  'landing12.faq.a4': 'Yes. The Library accepts supported files and scans, exposes real processing states, extracts concepts and supports grounded questions and transformations.',
  'landing12.faq.q5': 'Can I learn a language?',
  'landing12.faq.a5': 'Yes. The Real Life Language Engine combines a CEFR curriculum, explicit language work, World Missions, oral practice, targeted repair, review and Can-Do evidence.',
  'landing12.faq.q6': 'How does the AI Professor work?',
  'landing12.faq.a6': 'It uses the active learner context and can explain, teach, question, assess or practise while preserving the Experience Session.',
  'landing12.faq.q7': 'How do reviews work?',
  'landing12.faq.a7': 'Review uses actual history and spaced repetition to prioritize knowledge that risks being forgotten. Non-AI review remains available independently of AI quotas.',
  'landing12.faq.q8': 'Which languages are available?',
  'landing12.faq.a8': 'The shared registry currently contains 27 learning languages. Interface language and learning language are always separate choices.',
  'landing12.faq.q9': 'Does Research search the Web?',
  'landing12.faq.a9': 'Research can work across My Brain and your Library today. The external Web provider is not configured in the current deployment, so the Landing does not claim that it is.',
  'landing12.faq.q10': 'Are my data private?',
  'landing12.faq.a10': 'Authenticated controls cover AI memory, documents, consents, export and account deletion. This page does not add legal or infrastructure promises beyond those controls.',
  'landing12.faq.q11': 'What is the difference between Free, Pro and Max?',
  'landing12.faq.a11': 'They are the three individual plan levels in the backend catalog. Final prices, quotas and plan benefits will be configured after the public beta.',
  'landing12.faq.q12': 'Where can I use Second Brain?',
  'landing12.faq.a12': 'The Web experience is available in this application. Android and iOS are technically prepared without public store links; Windows and macOS distribution is still upcoming.',

