  'landing.faq.title': 'Questions fréquentes',
  'landing.faq.q1': 'Second Brain est-il simplement un chatbot ?',
  'landing.faq.a1': 'Non. C’est un environnement d’apprentissage personnel : il comprend ton contenu, l’enseigne et retient ta progression dans le temps.',
