  'landing.faq.q5': 'Qu’est-ce que le Jumeau Numérique ?',
  'landing.faq.a5': 'Une mémoire personnalisée de ton apprentissage — ce que tu comprends, maîtrises, oublies et vises.',
  'landing.faq.q6': 'Comment fonctionnent la mémoire et la révision ?',
  'landing.faq.a6': 'Un moteur de répétition espacée (FSRS) planifie les révisions au bon moment pour retenir plus avec moins d’effort.',
  'landing.faq.q7': 'Puis-je utiliser Second Brain pour mes travaux académiques ?',
  'landing.faq.a7': 'Oui. L’Academic Workspace guide TP, devoirs, rapports et plus — en enseignant la démarche, pas seulement la réponse.',
  'landing.faq.q8': 'Comment fonctionne l’apprentissage des langues ?',
  'landing.faq.a8': 'Immersion, conversation, pratique orale et shadowing — et une aide pour comprendre la langue de ton propre cursus.',
  'landing.faq.q9': 'Comment mes données sont-elles protégées ?',
  'landing.faq.a9': 'Tes données d’apprentissage alimentent ton expérience. Tu contrôles ton compte et peux gérer tes données depuis ton profil.',

