  'landing12.story.kicker': 'Un seul produit, une seule expérience',
  'landing12.story.title': 'Regarde la connaissance traverser tout le système',
  'landing12.story.lead': 'Une source ne s’arrête pas au stockage. Cette démonstration suit le même contexte du document jusqu’à la compréhension, la pratique, la révision et la production académique.',
  'landing12.story.documents.title': 'Un document devient une connaissance utilisable',
  'landing12.story.documents.short': 'Documents',
  'landing12.story.documents.desc': 'La Bibliothèque reçoit la source. Document Intelligence la lit, extrait les concepts et prépare les questions sourcées sans inventer de progression.',
  'landing12.story.brain.title': 'Les concepts rejoignent une carte cognitive connectée',
  'landing12.story.brain.short': 'Mon Cerveau',
  'landing12.story.brain.desc': 'Le jumeau cognitif rend visibles concepts, relations, forces et fragilités. Cet exemple public est illustratif, pas un score d’apprenant réel.',
  'landing12.story.professor.title': 'Le Professeur enseigne avec le même contexte',
  'landing12.story.professor.short': 'Professeur IA',
  'landing12.story.professor.desc': 'Le document, le concept ciblé et l’objectif suivent la session. L’expérience peut devenir explication, leçon, question ou pratique guidée.',
  'landing12.story.oral.title': 'La compréhension devient une pratique orale',
  'landing12.story.oral.short': 'Oral & Voix',
  'landing12.story.oral.desc': 'Écoute, transcription et réponse sont des états distincts et lisibles. Le texte reste visible ; aucune fausse waveform ne prétend mesurer la parole.',
  'landing12.story.review.title': 'Une notion fragile devient une révision',
  'landing12.story.review.short': 'Réviser',
  'landing12.story.review.desc': 'Le moteur de révision consolide au bon moment. La date montrée ici est explicitement démonstrative, pas une vraie planification.',
